import React,{useState,useEffect,useRef,useContext,createContext,useId} from 'react';
import {createRoot} from 'react-dom/client';
import * as M from './model.js';
import Scene from './Scene.jsx';
import landscape from './assets/colchagua.png';
import identity from './assets/identidad.png';
import './style.css';

const C=createContext();
const useClub=()=>useContext(C);
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const ageLabel=e=>e.maxAge===120?`Desde ${e.minAge} años`:`${e.minAge}–${e.maxAge} años`;
const vacancies=n=>`${n} ${n===1?'cupo disponible':'cupos disponibles'}`;
const date=d=>new Date(d+'T12:00:00').toLocaleDateString('es-CL',{day:'numeric',month:'long'});
const icons={arrow:'M4 12h16m-6-6 6 6-6 6',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM12 7v5',link:'m9 15 6-6M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',ticket:'M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4zM15 5v3m0 3v2m0 3v3',screen:'M2 3h20v14H2zM12 17v4M7 21h10',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',shop:'M4 10v11h16V10M2 10l3-7h14l3 7M2 10c2 3 4 3 5 0 2 3 4 3 5 0 2 3 4 3 5 0 2 3 4 3 5 0M9 21v-7h6v7',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M22 21v-2a4 4 0 0 0-3-3.8M16 3a4 4 0 0 1 0 8',leaf:'M20 3C8 1 1 8 5 16s17 2 15-13ZM4 21 16 9',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 10h16',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',card:'M3 4h18v16H3zM6 8h5M6 12h7M6 16h4M16 8v8',help:'M9 8a3 3 0 1 1 5 3c-2 1-2 1-2 3M12 17v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',edit:'m4 16 12-12 4 4L8 20H4zM13 7l4 4',coffee:'M4 7h12v9c0 6-12 6-12 0zM16 8h3c5 0 4 7-3 7M7 2v2M12 2v2'};
function Icon({name,size=20}){return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={icons[name]||icons.leaf}/></svg>}
function Seal(){return <span className="seal" aria-hidden="true"><img src={identity} alt=""/></span>}
function Button({children,icon='arrow',secondary=false,...props}){return <button className={'button '+(secondary?'secondary':'')} {...props}>{children}{icon&&<Icon name={icon} size={18}/>}</button>}
function Status({children}){return <span className={'status '+(['Activa','Confirmada','Canjeado','Completada','Cumplido','Activo','Abierta'].includes(children)?'positive':['Cancelada','Rechazada','Vencido','Retirada'].includes(children)?'muted':'')}>{children}</span>}
function Heading({eyebrow,title,description,children}){return <div className="section-heading"><div>{eyebrow&&<div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1>{description&&<p>{description}</p>}</div>{children}</div>}
function Empty({title,children}){return <div className="empty"><Icon name="leaf" size={32}/><h3>{title}</h3>{children}</div>}
function Field({label,children,...props}){const fieldId=useId();return <div className="field"><label htmlFor={fieldId}>{label}</label>{children?React.cloneElement(children,{id:fieldId}):<input id={fieldId} {...props}/>}</div>}
function Modal({title,onClose,children}){const ref=useRef();useEffect(()=>{const before=document.activeElement;ref.current.focus();const old=document.body.style.overflow;document.body.style.overflow='hidden';const key=e=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const nodes=[...ref.current.querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')];if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===ref.current)){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',key);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',key);before?.focus()};},[]);return <div className="overlay" onClick={e=>e.target===e.currentTarget&&onClose()}><section className="modal" role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} ref={ref}><header><h2>{title}</h2><button className="icon-button" aria-label="Cerrar ventana" onClick={onClose}><Icon name="close"/></button></header>{children}</section></div>}
function Form({onSave,children,label='Guardar',initial,footnote}){const [error,setError]=useState('');return <form onSubmit={e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));try{onSave(values);setError('')}catch(err){setError(err.message)}}}>{children}{footnote&&<p className="form-note">{footnote}</p>}{error&&<p role="alert" className="error">{error}</p>}<Button type="submit">{label}</Button></form>}

function App(){
 const [state,setState]=useState(()=>{try{return M.migrateState(JSON.parse(localStorage.getItem(M.KEY)||localStorage.getItem(M.LEGACY_KEY)||'null'))}catch{return M.initialState()}});
 const [mode,setMode]=useState(new URLSearchParams(location.search).get('vista')==='comercio'?'business':'client');
 const [page,setPage]=useState(new URLSearchParams(location.search).get('vista')==='comercio'?'home':'discover');
 const [businessId,setBusinessId]=useState('olivo'),[memberId,setMemberId]=useState('ana'),[modal,setModal]=useState(null),[toast,setToast]=useState(''),[simple,setSimple]=useState(false),[storageError,setStorageError]=useState(false),[validationCode,setValidationCode]=useState('');
 const stateRef=useRef(state);stateRef.current=state;
 useEffect(()=>{try{localStorage.setItem(M.KEY,JSON.stringify(state))}catch{setStorageError(true)}},[]);
 useEffect(()=>{const listener=e=>{if(e.key===M.KEY&&e.newValue){try{const next=M.migrateState(JSON.parse(e.newValue));stateRef.current=next;setState(next)}catch{}}};window.addEventListener('storage',listener);return()=>window.removeEventListener('storage',listener)},[]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(t)}},[toast]);
 const run=(fn,message)=>{let current=stateRef.current;try{const disk=localStorage.getItem(M.KEY);if(disk)current=M.migrateState(JSON.parse(disk))}catch{}const next=fn(current);stateRef.current=next;setState(next);try{localStorage.setItem(M.KEY,JSON.stringify(next));setStorageError(false)}catch{setStorageError(true)}if(message)setToast(message);return next;};
 const open=m=>setModal(m),navigate=p=>{setPage(p);setModal(null);window.scrollTo({top:0,behavior:'instant'})};
 const changeMode=m=>{setMode(m);navigate(m==='client'?'discover':'home');};
 const businesses=M.allBusinesses(state),offers=M.allOffers(state),member=state.members.find(m=>m.id===memberId)||state.members[0],business=businesses.find(b=>b.id===businessId)||businesses[0];
 const context={s:state,run,mode,page,navigate,changeMode,open,close:()=>setModal(null),notify:setToast,businessId:business.id,setBusinessId,memberId:member.id,setMemberId,business,member,businesses,offers,simple,validationCode,setValidationCode};
 const navigation=mode==='client'?[['discover','Descubrir','search'],['passport','Mi pasaporte','card'],['club','Club de Amigos','users'],['collaborations','Colaboraciones','link']]:[['home','Mi comercio','shop'],['benefits','Pasaporte y beneficios','card'],['collaborations','Colaboraciones','link'],['club','Club de Amigos','users']];
 return <C.Provider value={context}><div className={'app '+(simple&&mode==='client'?'simple':'')} style={{'--landscape':`url(${landscape})`}}>
 <div className="demo-bar"><span><i/> PRUEBA LOCAL · 0.2</span><span className="demo-description">Negocios y actividades de ejemplo</span><button onClick={()=>open({type:'guide'})}>Cómo probar <Icon name="arrow" size={14}/></button></div>
 <header className="header"><button className="brand" onClick={()=>navigate(mode==='client'?'discover':'home')}><Seal/><span>CLUB SANTA CRUZ<small>COLCHAGUA · ENTRE AMIGOS</small></span></button><div className="role-switch" aria-label="Vista de prueba"><button aria-pressed={mode==='client'} className={mode==='client'?'active':''} onClick={()=>changeMode('client')}><Icon name="users" size={16}/> Soy cliente</button><button aria-pressed={mode==='business'} className={mode==='business'?'active':''} onClick={()=>changeMode('business')}><Icon name="shop" size={16}/> Soy comercio</button></div><button className="icon-button help" aria-label="Ayuda para probar" onClick={()=>open({type:'guide'})}><Icon name="help"/></button></header>
 <nav className="main-nav" aria-label="Secciones del club">{navigation.map(([key,label,icon])=><button key={key} aria-current={page===key?'page':undefined} className={page===key?'active':''} onClick={()=>navigate(key)}><Icon name={icon} size={18}/>{label}</button>)}<span className="nav-place"><Icon name="pin" size={15}/> Santa Cruz, Chile</span></nav>
 <div className="persona-bar">{mode==='client'?<><label>Probando como <select aria-label="Socio de prueba" value={member.id} onChange={e=>{setMemberId(e.target.value);setModal(null)}}>{state.members.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label><div><button onClick={()=>open({type:'family'})}><Icon name="users" size={16}/> Mi familia</button><button aria-pressed={simple} onClick={()=>setSimple(x=>!x)}>{simple?'Vista completa':'Vista simple'} <span className="text-size">Aa</span></button></div></>:<><label>Comercio de prueba <select aria-label="Comercio de prueba" value={business.id} onChange={e=>{setBusinessId(e.target.value);setModal(null);setValidationCode('')}}>{businesses.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><button onClick={()=>open({type:'register'})}><Icon name="plus" size={16}/> Agregar mi negocio</button></>}</div>
 {storageError&&<p className="error storage-warning">El navegador no permite guardar: los cambios durarán mientras mantengas esta página abierta.</p>}
 <main id="main">
 {simple&&mode==='client'&&<div className="simple-actions">{[['passport','Mi carnet','card'],['discover','Beneficios','ticket'],['club','Actividades','calendar'],['help','Ayuda','help']].map(([p,t,i])=><button key={p} onClick={()=>p==='help'?open({type:'guide'}):navigate(p)}><Icon name={i} size={28}/>{t}</button>)}</div>}
 {mode==='client'&&page==='discover'&&<Discover/>}
 {mode==='client'&&page==='passport'&&<Passport/>}
 {mode==='business'&&page==='home'&&<BusinessHome/>}
 {mode==='business'&&page==='benefits'&&<Benefits/>}
 {page==='collaborations'&&<Collaborations/>}
 {page==='club'&&<Club/>}
 {page==='screens'&&<Screens/>}
 </main>
 <footer><div><strong>Club Santa Cruz</strong><span>Entre amigos, crecemos todos.</span></div><p>Prueba local · Datos en este navegador · Imágenes conceptuales</p><button onClick={()=>open({type:'reset'})}>Reiniciar prueba</button></footer>
 {toast&&<div role="status" className="toast"><Icon name="check"/>{toast}<button aria-label="Cerrar aviso" onClick={()=>setToast('')}><Icon name="close" size={16}/></button></div>}
 {modal&&<Dialogs modal={modal}/>}</div></C.Provider>;
}

function OfferCard({o,manage=false}){const {s,businesses,memberId,open,run,businessId}=useClub();const b=businesses.find(b=>b.id===o.businessId),saved=s.favorites.some(f=>f.offerId===o.id&&f.memberId===memberId);const coupon=s.coupons.find(c=>c.offerId===o.id&&c.memberId===memberId);return <article className="offer-card"><div className="offer-image">{b.scene==='vineyard'?<div className="landscape"/>:<Scene type={b.scene}/>}<span className="benefit-tag">{o.discount}</span>{!manage&&<button className={'favorite '+(saved?'selected':'')} aria-label={(saved?'Quitar de favoritos: ':'Guardar favorito: ')+b.name} aria-pressed={saved} onClick={()=>run(s=>({...s,favorites:saved?s.favorites.filter(f=>!(f.memberId===memberId&&f.offerId===o.id)):[...s.favorites,{memberId,offerId:o.id}]}))}><Icon name="heart" size={18}/></button>}</div><div className="offer-body"><div className="eyebrow">{b.category} · {b.mode}</div><button className="business-name" onClick={()=>open({type:'business',id:b.id})}>{b.name}</button><h3>{o.title}</h3><p>{o.detail}</p><div className="offer-meta"><span>{M.remaining(s,o)} cupos</span><span>Hasta el {date(o.expires)}</span></div><div className="offer-actions">{manage?<><Status>{o.status}</Status><button className="text-button" onClick={()=>run(s=>M.toggleOffer(s,o.id,businessId),'Estado del beneficio actualizado')}>{o.status==='Activo'?'Pausar':'Reactivar'}</button></>:<button onClick={()=>open({type:'offer',id:o.id})}>{coupon?'Ver mi beneficio':'Conocer beneficio'}<Icon name="arrow" size={17}/></button>}</div></div></article>}
function Discover(){const {s,memberId,offers,businesses,navigate,open}=useClub();const [query,setQuery]=useState(''),[category,setCategory]=useState('Todos'),[mode,setMode]=useState('Todas'),[saved,setSaved]=useState(false);const results=offers.filter(o=>{const b=businesses.find(b=>b.id===o.businessId);return o.status==='Activo'&&o.expires>=M.futureDay(0)&&(category==='Todos'||b.category===category)&&(mode==='Todas'||b.mode===mode)&&normalize(`${b.name} ${b.tag} ${o.title}`).includes(normalize(query))&&(!saved||s.favorites.some(f=>f.memberId===memberId&&f.offerId===o.id));});return <>
 <section className="hero"><div className="hero-copy"><div className="eyebrow">NUESTRO VALLE. NUESTRA GENTE.</div><h1>Aquí nos conocemos.<br/>Aquí <em>crecemos.</em></h1><p>Descubre lo que hacen nuestros vecinos.<br/>Vuelve por lo bueno. Quédate por los vínculos.</p><Button onClick={()=>document.getElementById('discover-benefits').scrollIntoView({behavior:'smooth'})}>Descubrir beneficios</Button><div className="hero-foot"><span className="tiny-seal">SC</span> Un club de amigos de Colchagua</div></div><div className="hero-photo landscape" role="img" aria-label="Viñedos, huaso y caballo: imagen conceptual de Colchagua"><span className="photo-label">LA VIDA SE DISFRUTA CERCA</span><div className="hero-card"><Icon name="card" size={30}/><div><strong>Tu pasaporte al valle</strong><span>Cada visita, una nueva conexión.</span></div><button aria-label="Abrir mi pasaporte" onClick={()=>navigate('passport')}><Icon name="arrow"/></button></div></div></section>
 <div className="value-row"><span><Icon name="shop"/> Compra cerca</span><span><Icon name="link"/> Recomienda a un vecino</span><span><Icon name="users"/> Comparte un buen momento</span></div>
 <section id="discover-benefits"><Heading eyebrow="EL COMERCIO QUE NOS UNE" title="Buenas razones para volver" description="Beneficios de ejemplo, con condiciones claras y cupos limitados."><button className={'filter-toggle '+(saved?'selected':'')} aria-pressed={saved} onClick={()=>setSaved(x=>!x)}><Icon name="heart" size={17}/> Mis favoritos</button></Heading><div className="search-row"><label className="search"><Icon name="search"/><input aria-label="Buscar beneficios" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Un café, un oficio, una experiencia…"/></label><select aria-label="Modalidad de atención" value={mode} onChange={e=>setMode(e.target.value)}><option value="Todas">Todas las modalidades</option>{['En local','Desde casa','A domicilio'].map(x=><option key={x}>{x}</option>)}</select></div><div className="chips">{['Todos',...new Set(businesses.map(b=>b.category))].map(c=><button key={c} aria-pressed={category===c} className={category===c?'active':''} onClick={()=>setCategory(c)}>{c}</button>)}</div><div className="offer-grid">{results.map(o=><OfferCard key={o.id} o={o}/>)}</div>{!results.length&&<Empty title="No hay beneficios con estos filtros"><Button secondary onClick={()=>{setCategory('Todos');setMode('Todas');setQuery('');setSaved(false)}}>Ver todos</Button></Empty>}</section>
 <section className="community-banner"><div><div className="eyebrow">HAY MÁS FORMAS DE SER PARTE</div><h2>Nos juntamos.<br/>Nos hacemos bien.</h2><p>Fútbol, oficios, caminatas y música.<br/>Encuentra tu próximo encuentro en el Club de Amigos.</p><Button secondary onClick={()=>navigate('club')}>Ver actividades</Button></div><div className="community-photo" role="img" aria-label="Escena conceptual de vecinos compartiendo en un comercio"/></section>
 </>}

function Passport(){const {s,member,memberId,businesses,navigate,open,changeMode,setBusinessId,setValidationCode,notify}=useClub();const coupons=s.coupons.filter(c=>c.memberId===memberId),stamps=s.stamps.filter(x=>x.memberId===memberId),unique=[...new Set(stamps.map(s=>s.businessId))];return <>
 <Heading eyebrow="UN CARNET, MUCHAS CONEXIONES" title="Mi pasaporte Santa Cruz" description="Tus beneficios, tus visitas y tu lugar en el club."/>
 <div className="passport-layout"><section className="passport-card" id="print-card"><div className="passport-top"><Seal/><span>CLUB SANTA CRUZ<small>COLCHAGUA</small></span><Icon name="card" size={32}/></div><div className="eyebrow">CARNET DE SOCIO · PRUEBA</div><h2>{member.name}</h2><div className="passport-code">{member.card}</div><div className="passport-bottom"><span>Un club de amigos</span><span>Santa Cruz, Chile</span></div></section><section className="panel journey"><div className="eyebrow">PASAPORTE DEL VALLE</div><h2>Conoce tres comercios</h2><p>Cada comercio confirma tu visita y entrega un sello. El canje de un beneficio también suma una visita.</p><div className="stamp-slots">{[0,1,2].map(i=><div className={'stamp '+(unique[i]?'earned':'')} key={i}>{unique[i]?<Icon name="check" size={24}/>:<Icon name="leaf" size={24}/>}<span>{unique[i]?businesses.find(b=>b.id===unique[i])?.name:`Visita ${i+1}`}</span></div>)}</div><p className="progress-caption">{unique.length>=3?'¡Ruta completada! Ya eres Explorador del Valle.':`${Math.min(unique.length,3)} de 3 comercios descubiertos`}</p><small>Reconocimiento del club, sin premio monetario. Máximo un sello por comercio al día.</small></section></div>
 <div className="passport-tools"><button className="text-button" onClick={async()=>{try{await navigator.clipboard.writeText(member.card);notify('Código del carnet copiado')}catch{notify('Tu código es '+member.card)}}}>Copiar código del carnet</button><button className="text-button" onClick={()=>window.print()}>Imprimir carnet</button><button className="text-button" onClick={()=>{changeMode('business');navigate('benefits')}}>Probar entrega de sello <Icon name="arrow" size={16}/></button></div>
 <Heading title="Mis beneficios" description="El comercio confirma el canje. Aquí ves el resultado al instante."/>
 {!coupons.length?<Empty title="Tu primer beneficio te está esperando"><Button onClick={()=>navigate('discover')}>Descubrir beneficios</Button></Empty>:<div className="coupon-grid">{coupons.map(c=><article className={'coupon '+(M.couponStatus(c)!=='Disponible'?'used':'')} key={c.id}><div className="row between"><span className="eyebrow">{businesses.find(b=>b.id===c.businessId)?.name}</span><Status>{M.couponStatus(c)}</Status></div><h2>{c.discount}</h2><h3>{c.title}</h3><p>{c.detail}</p><div className="coupon-code">{c.code}</div><small>Válido hasta el {date(c.expires)} · Un solo canje</small>{M.couponStatus(c)==='Disponible'&&<Button secondary onClick={()=>{changeMode('business');setBusinessId(c.businessId);setValidationCode(c.code);navigate('benefits')}}>Probar canje en comercio</Button>}</article>)}</div>}
 {stamps.length>0&&<section className="panel history"><h2>Mis visitas</h2>{stamps.map(x=><div className="list-row" key={x.id}><span className="round-icon"><Icon name="check"/></span><div><strong>{businesses.find(b=>b.id===x.businessId)?.name}</strong><small>{x.reason} · {date(x.day)}</small></div></div>)}</section>}
 </>}

function BusinessHome(){const {s,business,businessId,businesses,offers,open,navigate}=useClub();const coupons=s.coupons.filter(c=>c.businessId===businessId),links=s.proposals.filter(p=>[p.from,p.to].includes(businessId)&&p.status==='Activa'),pending=s.proposals.filter(p=>p.awaiting===businessId&&p.status==='Pendiente');return <>
 <Heading eyebrow="EL VALOR DE HACER COMUNIDAD" title={`Hola, ${business.name}.`} description="Un lugar para recibir vecinos y encontrar buenos aliados."><Button onClick={()=>open({type:'proposal'})} icon="plus">Proponer colaboración</Button></Heading>
 <div className="metrics">{[[coupons.filter(c=>c.status==='Canjeado').length,'Canjes confirmados','ticket'],[s.stamps.filter(x=>x.businessId===businessId).length,'Visitas con sello','card'],[links.length,'Colaboraciones activas','link'],[s.events.filter(e=>e.owner===businessId&&e.status==='Abierta').length,'Actividades organizadas','users']].map(([n,t,icon])=><div className="metric" key={t}><Icon name={icon}/><strong>{n}</strong><span>{t}</span></div>)}</div>
 <div className="dashboard-grid"><section className="panel"><div className="panel-title"><h2>Tu perfil en el club</h2><button className="text-button" onClick={()=>open({type:'profile'})}>Editar <Icon name="edit" size={16}/></button></div><div className="profile-overview"><Scene type={business.scene}/><div><span className="eyebrow">{business.category}</span><h3>{business.name}</h3><p>{business.tag}</p><span className="meta"><Icon name="pin" size={15}/>{business.address}</span></div></div><div className="profile-needs"><strong>Busco y ofrezco</strong><p>{business.needs}</p></div><small>Perfil de prueba · {business.mode}</small></section><section className="panel wine-panel"><span className="eyebrow">CONEXIONES EN MOVIMIENTO</span><h2>{pending.length?`${pending.length} propuesta${pending.length>1?'s':''} por conversar`:'Tu próximo aliado está cerca'}</h2><p>{pending.length?'Revisa qué aporta cada comercio y acuerda condiciones antes de comenzar.':'Una recomendación, una vitrina compartida o una actividad pueden abrir nuevas oportunidades.'}</p><Button secondary onClick={()=>navigate('collaborations')}>Ver colaboraciones</Button><div className="panel-divider"/><button className="text-button" onClick={()=>navigate('benefits')}><Icon name="check"/> Validar un beneficio o entregar un sello</button></section></div>
 <Heading title="Podrían hacer un buen equipo" description="Comercios de ejemplo con servicios que se complementan."/><div className="business-grid">{businesses.filter(b=>b.id!==businessId).slice(0,3).map(b=><article className="panel partner-card" key={b.id}><span className="round-icon"><Icon name="shop"/></span><span className="eyebrow">{b.category}</span><h3>{b.name}</h3><p>{b.needs}</p><button className="text-button" onClick={()=>open({type:'proposal',to:b.id})}>Conversar una idea <Icon name="arrow" size={17}/></button></article>)}</div>
 <div className="subtle-banner"><Icon name="screen" size={32}/><div><strong>Tu pantalla puede ser la vitrina de otro vecino.</strong><p>Propón un intercambio o prepara un borrador de campaña.</p></div><Button secondary onClick={()=>navigate('screens')}>Ver pantallas</Button></div>
 </>}

function Benefits(){const {s,business,businessId,offers,open,run,validationCode,setValidationCode,member,navigate}=useClub();const [error,setError]=useState(''),[card,setCard]=useState(member.card),[result,setResult]=useState('');useEffect(()=>{setError('');setResult('')},[businessId]);return <>
 <Heading eyebrow="RECIBIR BIEN, INVITAR A VOLVER" title="Pasaporte y beneficios" description={`Entrega sellos y confirma canjes en ${business.name}.`}><Button onClick={()=>open({type:'new-offer'})} icon="plus">Crear beneficio</Button></Heading>
 <div className="validation-grid"><section className="panel"><span className="round-icon"><Icon name="ticket"/></span><h2>Canjear un beneficio</h2><p>Introduce el código que muestra el cliente.</p><form onSubmit={e=>{e.preventDefault();try{run(s=>M.redeemCoupon(s,validationCode,businessId),'Canje confirmado. El cliente ya lo ve en su pasaporte.');setResult('Beneficio canjeado. Visita registrada en el pasaporte.');setValidationCode('');setError('')}catch(err){setError(err.message)}}}><Field label="Código del beneficio" value={validationCode} onChange={e=>setValidationCode(e.target.value)} placeholder="CSC-XXXXXXXX" required autoComplete="off"/><Button type="submit" icon="check">Confirmar canje</Button></form>{error&&<p className="error" role="alert">{error}</p>}{result&&<p className="success" role="status">{result}</p>}<small>La pausa del beneficio no invalida cupones ya emitidos.</small></section><section className="panel stamp-panel"><span className="round-icon"><Icon name="card"/></span><h2>Entregar un sello</h2><p>Confirma una visita al comercio usando el carnet del socio.</p><Form onSave={v=>run(s=>M.awardStamp(s,v.card,businessId),'Sello entregado. Ya aparece en el pasaporte del cliente.')} label="Confirmar visita y dar sello"><Field label="Código del carnet" name="card" value={card} onChange={e=>setCard(e.target.value)} placeholder="SC-1001" required/></Form><small>Ana · SC-1001 / Tomás · SC-1002.<br/>Elena · SC-1003 / Nico · SC-1004.<br/>Máximo un sello diario por comercio y socio.</small></section></div>
 <Heading title="Beneficios de mi comercio" description="Los cupos se reservan al emitir el cupón. Las condiciones quedan guardadas con él."/><div className="offer-grid">{offers.filter(o=>o.businessId===businessId).map(o=><OfferCard key={o.id} o={o} manage/>)}</div>{!offers.some(o=>o.businessId===businessId)&&<Empty title="Publica tu primer beneficio"><Button onClick={()=>open({type:'new-offer'})}>Crear beneficio</Button></Empty>}
 <section className="panel history"><h2>Registro de cupones</h2>{s.coupons.filter(c=>c.businessId===businessId).length?s.coupons.filter(c=>c.businessId===businessId).map(c=><div className="list-row" key={c.id}><div><strong>{s.members.find(m=>m.id===c.memberId)?.name} · {c.discount}</strong><small>{c.code} · {c.title}</small></div><Status>{M.couponStatus(c)}</Status>{M.couponStatus(c)==='Disponible'&&<button className="text-button" onClick={()=>{setValidationCode(c.code);window.scrollTo({top:0,behavior:'smooth'})}}>Usar código</button>}</div>):<p>Aún no hay cupones emitidos. Prueba obtener uno desde Soy cliente.</p>}</section>
 </>}

function Collaborations(){const {s,businessId,businesses,mode,open,run,setBusinessId}=useClub();const [filter,setFilter]=useState('Todas'),[query,setQuery]=useState('');const list=s.proposals.filter(p=>mode==='business'?[p.from,p.to].includes(businessId):['Activa','Completada'].includes(p.status)).filter(p=>filter==='Todas'||p.status===filter);const name=id=>businesses.find(b=>b.id===id)?.name;return <>
 <Heading eyebrow="UNO RECOMIENDA. TODOS CRECEMOS." title={mode==='business'?'Colaboraciones con sentido':'Una red de buenas conexiones'} description={mode==='business'?'Aportes claros, plazos acordados y aceptación de ambas partes.':'Conoce las colaboraciones activas de los comercios de esta prueba.'}>{mode==='business'&&<Button icon="plus" onClick={()=>open({type:'proposal'})}>Nueva propuesta</Button>}</Heading>
 {mode==='business'&&<div className="chips">{['Todas','Pendiente','Activa','Completada','Rechazada','Retirada'].map(x=><button key={x} className={filter===x?'active':''} onClick={()=>setFilter(x)}>{x==='Pendiente'?'Por acordar':x}</button>)}</div>}
 <div className="collaboration-list">{list.map(p=><article className="panel collaboration" key={p.id}><div className="row between"><span className="eyebrow">{p.type}</span><Status>{p.status}</Status></div><h2>{p.title}</h2><div className="partners-line"><span>{name(p.from)}</span><Icon name="link" size={18}/><span>{name(p.to)}</span></div><div className="agreement"><div><small>{name(p.from)} aporta</small><p>{p.offer}</p></div><div><small>{name(p.to)} aporta</small><p>{p.request}</p></div></div>{p.message&&<p>{p.message}</p>}<div className="agreement-dates"><Icon name="calendar" size={16}/> {date(p.start)} — {date(p.end)}</div>
 {mode==='business'&&<><div className="agreement-actions">{p.status==='Pendiente'&&p.awaiting===businessId?<><Button icon="check" onClick={()=>run(s=>M.respondProposal(s,p.id,businessId,'accept'),'Acuerdo activo para ambos comercios')}>Aceptar acuerdo</Button><Button secondary icon="edit" onClick={()=>open({type:'counter',proposal:p})}>Proponer ajustes</Button><button className="text-button" onClick={()=>open({type:'proposal-action',id:p.id,action:'reject'})}>Rechazar</button></>:p.status==='Pendiente'?<><span className="waiting">Esperando a {name(p.awaiting)}</span><button className="text-button" onClick={()=>{setBusinessId(p.awaiting)}}>Probar como {name(p.awaiting)} <Icon name="arrow" size={16}/></button><button className="text-button" onClick={()=>open({type:'proposal-action',id:p.id,action:'withdraw'})}>Retirar propuesta</button></>:p.status==='Activa'?<>{p.fulfilled.includes(businessId)?<span className="success-inline"><Icon name="check" size={16}/> Mi aporte está cumplido</span>:<Button secondary icon="check" onClick={()=>run(s=>M.respondProposal(s,p.id,businessId,'fulfill'),'Tu aporte quedó confirmado')}>Confirmar mi aporte cumplido</Button>}<span>{p.fulfilled.length} de 2 aportes confirmados</span></>:null}</div><details><summary>Historial del acuerdo</summary>{p.history.length?p.history.map((h,i)=><p key={i}><strong>{name(h.actor)}</strong> · {h.action}</p>):<p>Acuerdo recuperado de la primera versión.</p>}</details></>}
 </article>)}</div>{!list.length&&<Empty title={mode==='business'?'Aquí aparecerán tus acuerdos':'Las buenas alianzas están por comenzar'}><p>{mode==='business'?'Propón una idea a un negocio de la comunidad.':'Prueba aceptar una colaboración desde Soy comercio y vuelve para verla.'}</p></Empty>}
 {mode==='business'&&<><Heading title="Encuentra tu próximo aliado" description="Explora por rubro, nombre o lo que cada negocio busca."/><label className="search"><Icon name="search"/><input aria-label="Buscar aliados" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Alojamiento, artesanía, vitrina…"/></label><div className="business-grid allies">{businesses.filter(b=>b.id!==businessId&&normalize(`${b.name} ${b.category} ${b.needs}`).includes(normalize(query))).map(b=><article className="panel partner-card" key={b.id}><span className="eyebrow">{b.category} · {b.mode}</span><h3>{b.name}</h3><p>{b.needs}</p><Button secondary onClick={()=>open({type:'proposal',to:b.id})}>Proponer colaboración</Button></article>)}</div></>}
 </>}

function ActivityArt({event}){return <div className={'activity-art '+event.scene}>{event.scene==='vineyard'?<div className="landscape"/>:event.scene==='pottery'?<Scene type="pottery"/>:<><div className="art-lines"/><span className="activity-symbol">{event.scene==='football'?'⚽':'♫'}</span></>}<span className="date-badge"><b>{new Date(event.date+'T12:00:00').getDate()}</b>{new Date(event.date+'T12:00:00').toLocaleDateString('es-CL',{month:'short'}).replace('.','')}</span></div>}
function Club(){const {s,mode,businessId,memberId,businesses,open}=useClub();const [category,setCategory]=useState('Todas'),[onlyMine,setOnlyMine]=useState(false);const regs=s.registrations.filter(r=>r.memberId===memberId&&r.status!=='Cancelada');const events=s.events.filter(e=>(category==='Todas'||e.category===category)&&(!onlyMine||(mode==='business'?e.owner===businessId:regs.some(r=>r.eventId===e.id)))).sort((a,b)=>a.date.localeCompare(b.date));return <>
 <Heading eyebrow="LA VIDA DEL CLUB" title="Hay un lugar para ti." description="Nos encontramos para jugar, aprender y compartir lo que sabemos.">{mode==='business'?<Button icon="plus" onClick={()=>open({type:'new-event'})}>Organizar actividad</Button>:<Button secondary icon="users" onClick={()=>open({type:'family'})}>Mi familia</Button>}</Heading>
 <div className="club-intro"><Icon name="users" size={32}/><p>Todo encuentro tiene un responsable.<br/><strong>Y todos podemos aportar algo.</strong></p><span>Niños y familias · Jóvenes · Adultos mayores</span></div>
 {mode==='client'&&s.notices.filter(n=>n.memberId===memberId).length>0&&<div className="notices" role="status">{s.notices.filter(n=>n.memberId===memberId).slice(0,4).map(n=><p key={n.id}><Icon name="calendar" size={16}/>{n.text}</p>)}</div>}
 <div className="club-filters"><div className="chips">{['Todas','Niños y familias','Jóvenes','Adultos mayores','Todo público'].map(c=><button className={category===c?'active':''} onClick={()=>setCategory(c)} key={c}>{c}</button>)}</div><button className={'filter-toggle '+(onlyMine?'selected':'')} aria-pressed={onlyMine} onClick={()=>setOnlyMine(x=>!x)}>{mode==='business'?'Mis actividades':'Mis inscripciones'}</button></div>
 <div className="activity-grid">{events.map(e=>{const full=M.confirmedCount(s,e.id)>=e.capacity;const mine=regs.filter(r=>r.eventId===e.id);return <article className="activity-card" key={e.id}><ActivityArt event={e}/><div className="activity-body"><div className="row between"><span className="eyebrow">{e.category}</span>{e.status==='Cancelada'&&<Status>Cancelada</Status>}</div><h2>{e.title}</h2><p>{e.description}</p><span className="meta"><Icon name="clock" size={16}/>{e.time} · {ageLabel(e)}</span><span className="meta"><Icon name="pin" size={16}/>{e.place}</span><div className="activity-owner">Organiza <strong>{businesses.find(b=>b.id===e.owner)?.name}</strong></div><div className="activity-footer"><span>{e.status==='Cancelada'?'Actividad cancelada':full?'Lista de espera':vacancies(e.capacity-M.confirmedCount(s,e.id))}</span>{mode==='client'&&mine.length>0&&<span className="enrolled-dot">{mine.length} inscripción{mine.length>1?'es':''}</span>}</div><Button secondary onClick={()=>open({type:'event',id:e.id})}>{mode==='business'&&e.owner===businessId?'Gestionar actividad':'Ver encuentro'}</Button></div></article>})}</div>{!events.length&&<Empty title="Aún no hay actividades en esta selección"><Button secondary onClick={()=>{setOnlyMine(false);setCategory('Todas')}}>Ver todos los encuentros</Button></Empty>}
 </>}

function EventDetail({eventId}){const {s,mode,memberId,businessId,businesses,run,open}=useClub();const e=s.events.find(x=>x.id===eventId),mine=M.participants(s,memberId),[participant,setParticipant]=useState(''),[error,setError]=useState(''),[consent,setConsent]=useState(false);const manager=mode==='business'&&e.owner===businessId,actor=mode==='business'?'business:'+businessId:'member:'+memberId;const regs=s.registrations.filter(r=>r.eventId===e.id&&(manager||(mode==='client'&&r.memberId===memberId)));const action=fn=>{try{run(fn);setError('')}catch(err){setError(err.message)}};return <>
 <ActivityArt event={e}/><div className="row between"><span className="eyebrow">{e.category}</span><Status>{e.status}</Status></div><h3 className="event-title">{e.title}</h3><p>{e.description}</p><div className="conditions"><p><Icon name="calendar" size={16}/> {date(e.date)} · {e.time}</p><p><Icon name="pin" size={16}/> {e.place}</p><p><Icon name="users" size={16}/> {ageLabel(e)} · {M.confirmedCount(s,e.id)} de {e.capacity} cupos ocupados</p><p>Responsable: <strong>{businesses.find(b=>b.id===e.owner)?.name}</strong></p></div>
 {mode==='client'&&e.status==='Abierta'&&<form onSubmit={ev=>{ev.preventDefault();action(s=>M.enroll(s,e.id,memberId,participant,consent))}}><Field label="¿A quién quieres inscribir?"><select value={participant} onChange={ev=>setParticipant(ev.target.value)} required><option value="">Elige una persona</option>{mine.map(p=><option key={p.id} value={p.id} disabled={p.age<e.minAge||p.age>e.maxAge}>{p.name} · {p.age} años{p.age<e.minAge||p.age>e.maxAge?' (fuera del rango)':''}</option>)}</select></Field><label className="checkbox"><input type="checkbox" checked={consent} onChange={ev=>setConsent(ev.target.checked)} required/><span>Leí las condiciones. Si inscribo a un menor, confirmo que actúo como su apoderado responsable.</span></label><Button type="submit" icon="plus">{M.confirmedCount(s,e.id)<e.capacity?'Confirmar inscripción':'Unirme a la lista de espera'}</Button></form>}
 {error&&<p className="error" role="alert">{error}</p>}
 {regs.length>0&&<section className="registrations"><h3>{manager?'Participantes y asistencia':'Mis inscripciones'}</h3>{regs.map(r=><div className="registration" key={r.id}><div><strong>{r.name}</strong><small>{manager?`Apoderado: ${s.members.find(m=>m.id===r.memberId)?.name}`:r.age+' años'}</small><Status>{r.status}</Status></div>{r.status!=='Cancelada'&&(manager?r.status==='Confirmada'&&e.status==='Abierta'&&<button className={'attendance '+(r.attendance?'present':'')} onClick={()=>action(s=>M.markAttendance(s,r.id,businessId))}><Icon name="check" size={16}/>{r.attendance?'Asistió':'Marcar asistencia'}</button>:!r.attendance&&<button className="text-button" onClick={()=>action(s=>M.cancelRegistration(s,r.id,memberId))}>Cancelar inscripción</button>)}{!manager&&r.attendance&&<span className="success-inline">Asistencia confirmada</span>}</div>)}{manager&&<small>En esta prueba puedes simular la asistencia antes del día del encuentro.</small>}</section>}
 {e.tasks.length>0&&<section className="tasks"><h3>Entre todos sale mejor</h3><p>Elige un aporte que puedas cumplir.</p>{e.tasks.map(t=>{const commitments=s.commitments.filter(c=>c.eventId===e.id&&c.taskId===t.id&&c.status!=='Cancelado'),own=commitments.find(c=>c.actor===actor);return <div className="task" key={t.id}><div><strong>{t.title}</strong><small>{commitments.length} de {t.slots} colaboradores</small>{own&&<Status>{own.status}</Status>}</div>{e.status==='Abierta'&&<div className="task-actions">{own?.status==='Aceptado'&&<button className="text-button" onClick={()=>action(s=>M.fulfillCommitment(s,own.id,actor))}>Ya cumplí mi aporte</button>}{own?.status!=='Cumplido'&&<button className="button secondary" disabled={!own&&commitments.length>=t.slots} onClick={()=>action(s=>M.toggleCommitment(s,e.id,t.id,actor))}>{own?'Liberar aporte':commitments.length>=t.slots?'Completo':'Yo colaboro'}</button>}</div>}</div>})}</section>}
 {manager&&e.status==='Abierta'&&<button className="danger-link" onClick={()=>open({type:'cancel-event',id:e.id})}>Cancelar actividad y avisar a inscritos</button>}
 <p className="form-note">Encuentro ficticio. Las inscripciones y avisos se guardan en esta prueba; no reservan lugares reales ni envían mensajes.</p>
 </>}

function BusinessFields({b={}}){return <><Field label="Nombre del negocio" name="name" defaultValue={b.name} required maxLength={60}/><div className="form-columns"><Field label="Rubro"><select name="category" defaultValue={b.category||'Tiendas y oficios'}>{['Gastronomía','Viñas y turismo','Tiendas y oficios','Alojamientos','Servicios','Bienestar'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Modalidad"><select name="mode" defaultValue={b.mode||'En local'}>{['En local','Desde casa','A domicilio'].map(x=><option key={x}>{x}</option>)}</select></Field></div><Field label="Qué ofreces" name="tag" defaultValue={b.tag} required maxLength={120}/><Field label="Dónde atiendes" name="address" defaultValue={b.address} required maxLength={120} placeholder="Sector o dirección de ejemplo"/><Field label="Qué buscas y qué puedes aportar"><textarea name="needs" defaultValue={b.needs} required maxLength={400}/></Field></>}
function ProposalFields({p={},to,businessId,businesses,counter=false}){return <>{!counter&&<Field label="Comercio con el que quieres colaborar"><select name="to" defaultValue={to||businesses.find(b=>b.id!==businessId)?.id}>{businesses.filter(b=>b.id!==businessId).map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></Field>}<Field label="Título del acuerdo" name="title" defaultValue={p.title} required maxLength={80} placeholder="Una vitrina compartida"/><Field label="Tipo de colaboración"><select name="type" defaultValue={p.type||'Promoción cruzada'}>{['Promoción cruzada','Intercambio de pantallas','Paquete conjunto','Proveedor local','Evento compartido'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label={counter?`Aporte de ${businesses.find(b=>b.id===p.from)?.name}`:'Lo que yo aporto'}><textarea name="offer" defaultValue={p.offer} required maxLength={500}/></Field><Field label={counter?`Aporte de ${businesses.find(b=>b.id===p.to)?.name}`:'Lo que propongo que aporte el otro comercio'}><textarea name="request" defaultValue={p.request} required maxLength={500}/></Field><div className="form-columns"><Field label="Inicio" name="start" type="date" defaultValue={p.start||M.futureDay(0)} required/><Field label="Término" name="end" type="date" defaultValue={p.end||M.futureDay(30)} min={M.futureDay(0)} required/></div><Field label="Cómo lo coordinaremos (opcional)"><textarea name="message" defaultValue={p.message} maxLength={400}/></Field></>}
function EventFields(){return <><Field label="Nombre del encuentro" name="title" required maxLength={80}/><Field label="Para quién"><select name="category">{['Todo público','Niños y familias','Jóvenes','Adultos mayores'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Descripción y condiciones"><textarea name="description" required maxLength={600}/></Field><Field label="Lugar de encuentro" name="place" required placeholder="Lugar de ejemplo" maxLength={140}/><div className="form-columns"><Field label="Fecha" name="date" type="date" defaultValue={M.futureDay(7)} min={M.futureDay(0)} required/><Field label="Hora" name="time" type="time" defaultValue="17:00" required/></div><div className="form-columns three"><Field label="Cupos" name="capacity" type="number" min="1" max="200" defaultValue="10" required/><Field label="Edad mínima" name="minAge" type="number" min="0" max="120" defaultValue="6" required/><Field label="Edad máxima" name="maxAge" type="number" min="0" max="120" defaultValue="120" required/></div><Field label="Un aporte que necesitamos (opcional)" name="task" maxLength={100} placeholder="Llevar agua, preparar materiales…"/><Field label="Personas para ese aporte" name="taskSlots" type="number" min="1" max="20" defaultValue="1"/></>}

function Dialogs({modal}){const {s,run,member,memberId,business,businessId,businesses,offers,open,close,navigate,changeMode,setBusinessId,notify}=useClub();const titles={offer:'Un beneficio para disfrutar',business:'Conoce a tu vecino',guide:'Probemos el club juntos',family:'Mi familia en el club',profile:'Mi perfil de comercio',register:'Agregar mi negocio de prueba','new-offer':'Invita a tus vecinos a volver',proposal:'Una colaboración empieza aquí',counter:'Ajustemos el acuerdo','proposal-action':'Confirmar decisión',event:'Un encuentro entre amigos','new-event':'Organicemos un encuentro','cancel-event':'Cancelar el encuentro',reset:'Volver al inicio de la prueba',campaign:'Borrador de campaña'};let content;
 if(modal.type==='offer'){const o=offers.find(o=>o.id===modal.id),b=businesses.find(b=>b.id===o.businessId),coupon=s.coupons.find(c=>c.offerId===o.id&&c.memberId===memberId);content=<><div className="offer-detail-art">{b.scene==='vineyard'?<div className="landscape"/>:<Scene type={b.scene}/>}<strong>{o.discount}</strong></div><span className="eyebrow">{b.category} · {b.mode}</span><h3 className="event-title">{b.name}</h3><p>{o.title}</p><div className="conditions"><strong>Condiciones del beneficio</strong><p>{o.detail}</p><p>{M.remaining(s,o)} cupos · Hasta el {date(o.expires)} · Una vez por socio</p><p><Icon name="pin" size={16}/>{b.address}</p></div><Form label={coupon?'Ver en mi pasaporte':'Guardar beneficio en mi pasaporte'} onSave={()=>{if(!coupon)run(s=>M.issueCoupon(s,o.id,memberId),'Beneficio guardado en tu pasaporte');changeMode('client');navigate('passport')}} footnote="Beneficio de prueba, sin validez en comercios reales."/></>;}
 if(modal.type==='business'){const b=businesses.find(b=>b.id===modal.id);content=<><Scene type={b.scene}/><h3 className="event-title">{b.name}</h3><p>{b.tag}</p><div className="conditions"><p>{b.category} · {b.mode}</p><p>{b.address}</p><strong>Busco y ofrezco</strong><p>{b.needs}</p></div><span className="form-note">Perfil de ejemplo, sin afiliación comercial real.</span></>;}
 if(modal.type==='profile'||modal.type==='register')content=<Form label={modal.type==='register'?'Crear perfil de prueba':'Guardar perfil'} onSave={v=>{const next=run(s=>M.saveBusiness(s,v,modal.type==='profile'?businessId:undefined),'Perfil actualizado');if(modal.type==='register')setBusinessId(next.customBusinesses.at(-1).id);navigate('home')}} footnote="Este registro es local. No verifica identidad ni crea una cuenta real."><BusinessFields b={modal.type==='profile'?business:{}}/></Form>;
 if(modal.type==='new-offer')content=<Form label="Publicar beneficio de prueba" onSave={v=>{run(s=>M.addOffer(s,businessId,v),'Beneficio visible para los clientes');close()}} footnote="Cada socio puede obtener un cupón. Puedes pausar nuevas emisiones; los cupones ya entregados conservan sus condiciones."><Field label="Nombre del beneficio" name="title" maxLength={70} required placeholder="Una pausa para dos"/><Field label="Beneficio visible" name="discount" required maxLength={24} placeholder="10%, un regalo, salida tardía…"/><Field label="Condiciones claras"><textarea name="detail" required maxLength={500} placeholder="Qué incluye, días, horario, compra mínima y exclusiones."/></Field><div className="form-columns"><Field label="Cupos totales" name="limit" type="number" min="1" max="10000" defaultValue="20" required/><Field label="Válido hasta" name="expires" type="date" min={M.futureDay(0)} defaultValue={M.futureDay(30)} required/></div></Form>;
 if(['proposal','counter'].includes(modal.type))content=<Form label={modal.type==='counter'?'Enviar ajuste para aceptación':'Enviar propuesta de prueba'} onSave={v=>{run(s=>modal.type==='counter'?M.respondProposal(s,modal.proposal.id,businessId,'counter',v):M.createProposal(s,businessId,v),'Propuesta lista para la otra parte');navigate('collaborations')}} footnote="El acuerdo se activa cuando ambas partes aceptan la misma versión. Los ajustes requieren una nueva aceptación."><ProposalFields p={modal.proposal} to={modal.to} businessId={businessId} businesses={businesses} counter={modal.type==='counter'}/></Form>;
 if(modal.type==='proposal-action')content=<><p>{modal.action==='reject'?'La propuesta quedará rechazada y conservará su historial.':'La propuesta se retirará y conservará su historial.'}</p><Form label="Confirmar decisión" onSave={()=>{run(s=>M.respondProposal(s,modal.id,businessId,modal.action),'Propuesta actualizada');close()}}/></>;
 if(modal.type==='event')content=<EventDetail eventId={modal.id}/>;
 if(modal.type==='new-event')content=<Form label="Publicar actividad de prueba" onSave={v=>{run(s=>M.createEvent(s,businessId,v),'Actividad publicada en el Club de Amigos');close()}} footnote={`Organiza ${business.name}. Actividad gratuita de ejemplo; no se envían invitaciones externas.`}><EventFields/></Form>;
 if(modal.type==='cancel-event')content=<><p>Se cancelarán las inscripciones y los aportes de esta actividad. Los participantes verán un aviso dentro de esta prueba. El historial se conservará.</p><Form label="Cancelar actividad y crear aviso" onSave={()=>{run(s=>M.cancelEvent(s,modal.id,businessId),'Actividad cancelada; avisos visibles para los inscritos');close()}}/></>;
 if(modal.type==='family')content=<><p>Usa nombres ficticios para explorar la prueba. Las inscripciones de menores se gestionan desde el perfil adulto.</p><Form label="Guardar mi nombre" onSave={v=>run(s=>M.saveMember(s,memberId,v.name),'Nombre actualizado')}><Field label="Mi nombre" name="name" defaultValue={member.name} required maxLength={40}/></Form><hr/><h3>Niños de mi familia</h3>{s.family.filter(p=>p.memberId===memberId).map(p=><div className="list-row" key={p.id}><strong>{p.name}</strong><span>{p.age} años</span></div>)}<Form label="Agregar familiar de prueba" onSave={v=>run(s=>M.addFamily(s,memberId,v),'Familiar agregado. Ya puedes inscribirlo.')}><div className="form-columns"><Field label="Nombre de pila" name="name" required maxLength={40}/><Field label="Edad" name="age" type="number" min="1" max="17" required/></div></Form></>;
 if(modal.type==='guide')content=<><p>Una prueba conectada: los cambios de un lado aparecen en el otro.</p><ol className="guide"><li><strong>Pasaporte.</strong> Como Ana, guarda un beneficio de Casa Olivo. Abre Mi pasaporte y pulsa Probar canje en comercio. Confírmalo y vuelve al cliente: verás el canje y un sello.</li><li><strong>Colaboraciones.</strong> Como Casa Olivo, revisa la propuesta de Taller Greda. Puedes aceptarla o proponer ajustes. Cambia el comercio para responder y confirmar los aportes.</li><li><strong>Club de Amigos.</strong> Inscribe a Camila en fútbol y después a Diego: quedará en espera. Cancela la primera inscripción y verás que Diego obtiene el cupo.</li><li><strong>Organiza y aporta.</strong> Como comercio, crea un encuentro. Como cliente, inscríbete o elige Yo colaboro. El organizador puede registrar asistencia.</li><li><strong>Tu propio negocio.</strong> Agrega un perfil de prueba, publica un beneficio y búscalo como cliente.</li></ol><div className="form-note">Datos en este navegador. Sin cuentas reales, pagos, mensajes externos ni promociones válidas. Los comercios y encuentros son ficticios. La persistencia local no ofrece seguridad ni sincronización entre dispositivos.</div><Button onClick={close}>Empezar a probar</Button></>;
 if(modal.type==='reset')content=<><p>Se restaurarán los ejemplos de esta versión. Se borrarán los datos que creaste en la prueba: perfiles, beneficios, sellos, acuerdos, inscripciones y campañas.</p><Button onClick={()=>{run(()=>M.initialState(),'Prueba reiniciada');setBusinessId('olivo');changeMode('client')}}>Reiniciar datos de prueba</Button><button className="text-button" onClick={close}>Conservar mis datos</button></>;
 if(modal.type==='campaign')content=<CampaignForm screen={modal.screen}/>;
 return <Modal key={modal.type+'-'+(modal.id||'')} title={titles[modal.type]} onClose={close}>{content}</Modal>;
}

function Screens(){const {s,businessId,businesses,open,navigate}=useClub();return <><Heading eyebrow="COMPARTE TU VITRINA" title="Pantallas que conectan" description="Explora intercambios y prepara campañas sin contratar espacios reales."><Button secondary onClick={()=>navigate('home')}>Volver a mi comercio</Button></Heading><div className="screen-banner"><Icon name="screen" size={60}/><div><h2>Tu espacio. La historia de un vecino.</h2><p>Una pantalla puede ayudar a descubrir lo que está a una cuadra.</p></div><Button secondary onClick={()=>open({type:'proposal'})}>Proponer intercambio</Button></div><div className="business-grid">{['olivo','refugio','alma'].map(id=><article className="panel partner-card" key={id}><Icon name="screen" size={28}/><h3>{businesses.find(b=>b.id===id)?.name}</h3><p>Pantalla de ejemplo · Disponibilidad ilustrativa</p><Button secondary onClick={()=>open({type:'campaign',screen:id})}>Preparar borrador</Button></article>)}</div><section className="panel history"><h2>Mis borradores</h2>{s.campaigns.filter(c=>c.businessId===businessId).map(c=><div className="list-row" key={c.id}><div><strong>{c.title}</strong><small>{businesses.find(b=>b.id===c.screen)?.name} · {c.days} días</small></div><span>{M.money(c.budget)}</span><Status>Borrador</Status></div>)}{!s.campaigns.some(c=>c.businessId===businessId)&&<p>Aún no preparas una campaña.</p>}</section></>}
function CampaignForm({screen}){const {businessId,businesses,run,close}=useClub();const [budget,setBudget]=useState(50000);return <Form label="Guardar borrador" onSave={v=>{run(s=>({...s,campaigns:[{id:crypto.randomUUID(),businessId,title:v.title.trim(),screen:v.screen,days:Number(v.days),budget:Number(v.budget)},...s.campaigns]}),'Borrador guardado, sin cobros');close()}} footnote="Reparto propuesto 80/20, sin IVA. No es una cotización ni reserva real."><Field label="Nombre de la campaña" name="title" required maxLength={70}/><Field label="Pantalla"><select name="screen" defaultValue={screen||'olivo'}>{['olivo','refugio','alma'].map(id=><option key={id} value={id}>{businesses.find(b=>b.id===id)?.name}</option>)}</select></Field><div className="form-columns"><Field label="Días" name="days" type="number" min="1" max="90" defaultValue="7" required/><Field label="Presupuesto CLP" name="budget" type="number" min="5000" max="1000000" step="1000" value={budget} onChange={e=>setBudget(Number(e.target.value))} required/></div><div className="conditions"><p>Local anfitrión · 80% <strong>{M.money(budget*.8)}</strong></p><p>Gestión del club · 20% <strong>{M.money(budget*.2)}</strong></p></div></Form>}

createRoot(document.getElementById('root')).render(<App/>);
